L["MALACRASS: Adds zuerst! Geistblitze heilen!"] = "MALACRASS: Adds first! Heal through Spirit Bolts!"
L["Seele entziehen: Klassenfähigkeiten beachten."] = "Siphon Soul: watch the class abilities."
L["Malacrass"] = "Malacrass"
L["Ein Symbol pro Add, Totenkopf zuerst."] = "One marker per add, skull first."
L["Zul'jin"] = "Zul'jin"
