L["Geröll per AoE. Tankwechsel bei Rüstung zermalmen."] = "AoE the Rubble. Tank swap on Crunch Armor."
L["Mimiron"] = "Mimiron"
L["Mimiron: Leviathan Mk II, VX-001, Luftkommandoeinheit, V-07-TR-0N"] = "Mimiron: Leviathan Mk II, VX-001, Aerial Command Unit, V-07-TR-0N"
