L["KLINGENSCHUPPE: Harpunen abschießen, am Boden Burst! Flammen raus!"] = "RAZORSCALE: Fire harpoons, burst when grounded! Out of the flames!"
L["Adds vom Offtank. Ab 50 % Tankwechsel bei Rüstung schmelzen."] = "Adds on the off-tank. From 50 % tank swap on Fuse Armor."
L["Thorim"] = "Thorim"
