L["Hardmode: Thorim innerhalb des Zeitfensters erreichen, dann kämpft Sif mit."] = "Hard mode: Reach Thorim within the time window, then Sif joins the fight."
L["THORIM: Gang-Team los! Arena-Adds töten, Blitzfelder meiden!"] = "THORIM: Gauntlet team go! Kill arena adds, avoid lightning fields!"
L["P2: Nicht vor den Boss, Tankwechsel."] = "P2: Not in front of the boss, tank swap."
L["XT-002 Dekonstruktor"] = "XT-002 Deconstructor"
