L["Tanks Cooldowns bei Dreschen. Champion hält die Lichtmauer."] = "Tanks cooldowns on Thrash. Champion holds the Wall of Light."
L["Thron des Donners"] = "Throne of Thunder"
L["Jin'rokh der Zerstörer"] = "Jin'rokh the Breaker"
L["- Statischer Ausbruch: Tankdebuff -> Tankwechsel."] = "- Static Burst: tank debuff -> tank swap."
