L["- Eiskomet: erzeugt Eis -> zum Löschen von Feuer nutzen."] = "- Ice Comet: creates ice -> use it to extinguish fire."
L["- Himmelsgestalt/Sterne: Raidschaden -> Cooldowns."] = "- Celestial form/stars: raid damage -> cooldowns."
