L["Mythisch: zusätzliche Phase mit Cho'gall."] = "Mythic: additional phase with Cho'gall."
L["MAR'GOK: Mal des Chaos - Tank raus! Minen ausweichen!"] = "MAR'GOK: Mark of Chaos - tank out! Dodge mines!"
